#include "stdafx.h"#include "ModbusTcpServerImpl.h"#include "Pool.h"KPool g_Pool;bool GetFirstACSObject(){  return g_Pool.GetFirstACSObject();}bool GetNextACSObject( DWORD & Type, void ** pData, char Name[256], char Data[256] ){  return g_Pool.GetNextACSObject( pData, Name, 256, Data, 256 );}bool ShowACSObject( void * pInfo, HWND hMainWnd, char * Name, void * pData ){  return g_Pool.ShowACSObject( pInfo, hMainWnd, Name, pData );}//////////////////////////////////////////////////////////////////////////bool KModbusTcpServerImpl::GetFirstACSObject(){  m_nAcsFindStep = 0;  return true;}bool KModbusTcpServerImpl::GetNextACSObject( void ** pData, char *Name, size_t sn, char *Data, size_t sd ){  if( -1!=m_nAcsFindStep )  {    m_nAcsFindStep = -1;    strcpy_s( Name, sn, ObjName );    strcpy_s( Data, sd, "ModbusTcpModelS" );    return true;  }  return false;}#include "../ModbusTcpDebug/ModbusTcpDebug.h"bool KModbusTcpServerImpl::ShowACSObject( HWND hMainWnd, char * Name, void * pData ){  if( !strcmp(ObjName, Name) )  {    SPrjCfg Config;    Config.pAIs = &m_AIs;    Config.pAOs = &m_AOs;    Config.pDIs = &m_DIs;    Config.pDOs = &m_DOs;    ShowDebugWnd( Name, hMainWnd, &Config, pData==(void*)1 ? true : false );    return true;  }  return false;}